// DataplaneServer is the server API for Dataplane service.
// All implementations must embed UnimplementedDataplaneServer
// for forward compatibility.
//
// Dataplane is the privileged agent's northbound API, served on a unix socket
// (/run/ngfw/agent.sock in production, the slot's NGFW_AGENT_SOCKET in tests). One agent process
// serves exactly one owner (NGFW_OWNER); see docs/contracts/proto.md "Ownership".
type DataplaneServer interface {
	// Apply converges the data plane (VPP + daemons) to the desired state of the selected
	// subsystems inside one transaction: validate → plan → apply → verify; on any error the
	// operations of this transaction are reverted in reverse order (status ROLLED_BACK). Applying the
	// same desired state twice yields an empty plan. With confirm_timeout_sec > 0 the agent
	// self-reverts to the previously confirmed state unless the transaction is confirmed in time.
	Apply(context.Context, *ApplyRequest) (*ApplyResponse, error)
	// Retrieve dumps the ACTUAL state of the selected subsystems from VPP and the daemons, filtered
	// to objects owned by this agent, decoded into the same DesiredState messages (canonicalised),
	// so that the caller can diff it against the running configuration. Never touches the data plane.
	Retrieve(context.Context, *RetrieveRequest) (*RetrieveResponse, error)
	// DryRun runs validation and planning for a desired state without applying anything and returns
	// the issues found plus the plan the reconciler would execute.
	DryRun(context.Context, *DryRunRequest) (*ValidationReport, error)
	// StreamStats pushes interface counters and per-worker CPU load read from the VPP stats segment,
	// one StatsBatch per interval (1 Hz by default), until the client cancels.
	StreamStats(*StreamStatsRequest, grpc.ServerStreamingServer[StatsBatch]) error
	// StreamEvents pushes asynchronous events (link state, reconcile start/done, confirm-timeout
	// reverts, errors) in the order the agent observes them, until the client cancels.
	StreamEvents(*StreamEventsRequest, grpc.ServerStreamingServer[Event]) error
	// Action runs a diagnostic (ping, traceroute, packet capture) and streams its output; the last
	// message is always a `done`. Cancelling the call stops the action.
	Action(*ActionRequest, grpc.ServerStreamingServer[ActionOutput]) error
	// Health reports agent and VPP connectivity. Cheap; polled by the API.
	Health(context.Context, *HealthRequest) (*HealthResponse, error)
	// InterfaceState dumps the live, read-only interface table (sw_if_index, type, admin/link state,
	// MTU, addresses, VRF) of every interface this agent can name: its own and untagged ones, never
	// another owner's (docs/contracts/proto.md §5 keeps such status out of Retrieve). Never mutates.
	InterfaceState(context.Context, *InterfaceStateRequest) (*InterfaceStateResponse, error)
	// Det44Sessions pages the DET44 sessions of one inside user (det44_session_dump; read-only).
	Det44Sessions(context.Context, *Det44SessionsRequest) (*Det44SessionsResponse, error)
	// Det44Lookup maps an inside address to its outside address and port block, or an outside
	// address and port back to the inside address (det44_forward / det44_reverse; read-only, for CGNAT logging).
	Det44Lookup(context.Context, *Det44LookupRequest) (*Det44LookupResponse, error)
	// CnatSessions pages the CNAT session table (cnat_session_dump; read-only).
	CnatSessions(context.Context, *CnatSessionsRequest) (*CnatSessionsResponse, error)
	// PkiFileState reports the PKI files this agent materialised for strongSwan (x509/, x509ca/, private/, x509crl/ under
	// its swanctl directory): kind, name, source reference, fingerprint (SHA-256 of the file; a private key only as an
	// HMAC-SHA256 under the agent-local key, D-096 — never key material), mode and presence on disk. Read-only (F-pki;
	// semantics in docs/status/tasks/F-pki-contract.md until docs/contracts/proto.md carries them).
	PkiFileState(context.Context, *PkiFileStateRequest) (*PkiFileStateResponse, error)
	// MplsState reads the live MPLS state of this owner: one page of an MPLS FIB (mpls_route_dump read once, filtered and
	// paged in the agent; the agent runs one MPLS FIB walk at a time) or the MPLS tunnels (mpls_tunnel_dump). Read-only
	// (docs/contracts/proto.md "F-mpls-srmpls: MplsState").
	MplsState(context.Context, *MplsStateRequest) (*MplsStateResponse, error)
	// LbState reports what VPP's lb plugin holds for this agent's VIPs (lb_vip_dump + lb_as_dump: prefix,
	// port, VIP type, DSCP / target port, each application server with its in-use or "removed" flag) and the
	// number of lb_vip_dump entries per VIP (deleted VIPs stay listed until the lb garbage collection, V20).
	// Read-only, never used as Retrieve: VPP 26.06 corrupts the protocol and table-length fields (D-063).
	LbState(context.Context, *LbStateRequest) (*LbStateResponse, error)
	// LbFlushVip flushes the sticky flow table of one of this agent's VIPs (lb_flush_vip), so established
	// flows are re-hashed over the current application servers. Refused unless the VIP was created by this
	// agent on the running VPP instance and has an application server in use.
	LbFlushVip(context.Context, *LbFlushVipRequest) (*LbFlushVipResponse, error)
	// QosPolicerState (F-qos-flat) lists this owner's policers — the `services.qos.policers` and the shapers, which the
	// agent realises as egress policers "shaper:<name>" — as VPP reports them (policer_dump_v2: configuration and token
	// buckets) with their conform / exceed / violate counters from the stats segment (/net/policer/*). Read-only
	// status, never part of Retrieve (§5); one policer walk at a time per agent (D-132).
	QosPolicerState(context.Context, *QosPolicerStateRequest) (*QosPolicerStateResponse, error)
	// QosPolicerReset (F-qos-flat) refills the token buckets of one of this owner's policers (policer_reset). VPP
	// keeps the counters (they restart only when the policer is re-created or updated).
	QosPolicerReset(context.Context, *QosPolicerResetRequest) (*QosPolicerResetResponse, error)
	// HostStackState reports the host stack as VPP sees it: session layer on/off (read-only probe),
	// this owner's session rules (from session_rules_v2_dump) and the app namespaces it applied. Never mutates.
	HostStackState(context.Context, *HostStackStateRequest) (*HostStackStateResponse, error)
	// SnmpState reports the snmpd renderer stage (F-snmp): daemon state read over SNMP, the pending
	// daemon action, the NGFW-MIB AgentX subagent. No credential value, ever. Never mutates.
	SnmpState(context.Context, *SnmpStateRequest) (*SnmpStateResponse, error)
	// IpfixState reports the live flow-export state (F-ipfix-sflow): IPFIX exporters from Retrieve
	// (exporter 0 read-only when this agent is not the globals owner), flowprobe and sFlow interfaces
	// of this owner, the VPP-global flowprobe/sFlow parameters and the sFlow node counters from the
	// stats segment. Dumps only; never mutates. UNAVAILABLE without VPP.
	IpfixState(context.Context, *IpfixStateRequest) (*IpfixStateResponse, error)
	// CaptureList lists the pcap files the agent keeps (moved out of VPP's /tmp to its capture directory, 0600,
	// retention by count and bytes) plus the running capture, and says whether packet trace and the packet
	// generator are available on this build (F-capture-trace). Never mutates.
	CaptureList(context.Context, *CaptureListRequest) (*CaptureListResponse, error)
	// CaptureRead streams one kept pcap file in chunks (the first chunk starts with the pcap global header).
	CaptureRead(*CaptureReadRequest, grpc.ServerStreamingServer[CaptureChunk]) error
	// CaptureDelete removes one kept pcap file and its record. NOT_FOUND for an unknown id; FAILED_PRECONDITION
	// for the running capture (stop it by cancelling its Action stream).
	CaptureDelete(context.Context, *CaptureDeleteRequest) (*CaptureDeleteResponse, error)
	// Srv6State dumps the live, read-only SRv6 objects of this owner (the local SIDs, policies and
	// steering entries its own Creates claimed): local SIDs with their good/bad traffic counters
	// (sr_localsids_with_packet_stats_dump), policies with their segment lists, steering entries.
	// Never another owner's objects, never the write-only globals. Never mutates; one walk at a time
	// (D-132) (docs/contracts/proto.md "F-srv6: Srv6State").
	Srv6State(context.Context, *Srv6StateRequest) (*Srv6StateResponse, error)
	// LispState reports the live LISP / LISP-GPE state (switches, locator sets, EID table / map-cache,
	// adjacencies, EID-table maps, resolvers) read from the VPP dumps (F-lisp). Never mutates.
	LispState(context.Context, *LispStateRequest) (*LispStateResponse, error)
	// BondState dumps the live state of this agent's bond interfaces (sw_bond_interface_dump): mode, load-balance
	// algorithm, member and active-member counts, and per member the weight, link state and, for LACP bonds, the
	// actor/partner LACP state (sw_member_interface_dump, sw_interface_lacp_dump; docs/contracts/proto.md "F-bonding").
	// Read-only; bounded (bonds and their members are few, one message).
	BondState(context.Context, *BondStateRequest) (*BondStateResponse, error)
	// BridgeDomainState dumps the live state of this agent's bridge domains (bd_tag "<owner>:…"): flags,
	// MAC aging, members with their port role and split-horizon group, the BVI and the number of learned
	// and static L2 FIB entries (docs/contracts/proto.md "F-bridge-l2"). Read-only.
	BridgeDomainState(context.Context, *BridgeDomainStateRequest) (*BridgeDomainStateResponse, error)
	// BridgeDomainMacs pages through the L2 FIB of one of this agent's bridge domains (l2_fib_table_dump),
	// at most 1000 entries per call, so a message stays bounded however large the table is. Read-only.
	BridgeDomainMacs(context.Context, *BridgeDomainMacsRequest) (*BridgeDomainMacsResponse, error)
	// LldpNeighbors lists the interfaces with LLDP enabled that this agent can name (its own and untagged ones,
	// never another owner's) with what was heard on each (lldp_dump: chassis id, port id, TTL, last heard/sent),
	// ordered by interface name, at most 1000 per call (docs/contracts/proto.md "F-loopback-bvi-gso-lldp-span").
	// Read-only.
	LldpNeighbors(context.Context, *LldpNeighborsRequest) (*LldpNeighborsResponse, error)
	// ListRoutes pages the live FIB of one VRF (ip_route_v2_dump read once, filtered and paged in the agent; only the
	// page crosses this boundary). Read-only state (docs/contracts/proto.md §11 F-vrf-static-ecmp: ListRoutes).
	ListRoutes(context.Context, *ListRoutesRequest) (*ListRoutesResponse, error)
	// ListNeighbors (F-neighbors-ra) dumps the live ARP/ND table (ip_neighbor_dump per interface and address family)
	// of every interface this agent can name — its own and untagged ones, never another owner's — filtered and paged
	// by the agent. Read-only; learned (dynamic) and static entries alike.
	ListNeighbors(context.Context, *ListNeighborsRequest) (*ListNeighborsResponse, error)
	// FqdnObjectState reports the agent's resolver state of every FQDN address object
	// (objects.addresses.<name> with type "fqdn"): the addresses in use (last-good answers survive a
	// failed refresh), when they were last resolved, the next scheduled refresh and the latest error.
	// Read-only runtime state (docs/contracts/proto.md §5 keeps it out of Retrieve). Never mutates.
	FqdnObjectState(context.Context, *FqdnObjectStateRequest) (*FqdnObjectStateResponse, error)
	// AclState reports the runtime state of this owner's L3/L4 ACLs (acl.lists): per list the VPP
	// acl_index, VPP rule count and summed hit counters; for one list a page (≤ 1000) of its
	// configuration rules by sequence with the number of VPP rules each expanded to and their hit
	// counters, mapped back through the agent's expansion; on request the ACLs bound to every
	// interface in VPP order, other owners' included (D-066), and the MACIP ACL per interface.
	// Read-only runtime state (docs/contracts/proto.md §5 keeps it out of Retrieve); counters come
	// from the stats segment, never a whole list in one message. Never mutates.
	AclState(context.Context, *AclStateRequest) (*AclStateResponse, error)
	// HostAclState reports the host firewall the agent rendered from `acl.host*` (the nftables table
	// `inet ngfw`): its sets, chains and rules with per-rule packet/byte counters read from
	// `nft -j list table`, and whether the kernel table still matches the applied rendering.
	// Read-only runtime state (docs/contracts/proto.md §5 keeps counters out of Retrieve). Never mutates.
	HostAclState(context.Context, *HostAclStateRequest) (*HostAclStateResponse, error)
	// NatSessions pages the live NAT44-ED session table of this owner (read-only, never mutates). VPP
	// dumps sessions per user (inside host), so the agent pages over the users first and dumps only
	// the users that cover the requested page: one response carries at most `limit` (≤ 1000)
	// sessions, never the whole table (docs/contracts/proto.md §11).
	NatSessions(context.Context, *NatSessionsRequest) (*NatSessionsResponse, error)
	// NatSummary reports this owner's NAT44-ED totals and per-pool usage (read-only; served from a
	// cache of up to 30 s, see retrieved_at).
	NatSummary(context.Context, *NatSummaryRequest) (*NatSummaryResponse, error)
	// WireguardState dumps the live, read-only WireGuard state of this agent's own wg<N> interfaces and
	// their peers (handshake flags, learnt endpoint, interface counters); never keys, never another
	// owner's interfaces. Never mutates (docs/contracts/proto.md "F-wireguard: WireguardState").
	WireguardState(context.Context, *WireguardStateRequest) (*WireguardStateResponse, error)
	// RoutingState reads the live routing-daemon state (FRR, P12): BGP instances and neighbours, FRR RIB counts, this
	// owner's linux-cp pairs, registered FRR state readers by key and a bounded RIB lookup. Read-only state
	// (docs/contracts/proto.md §11 P12: RoutingState); never part of Retrieve.
	RoutingState(context.Context, *RoutingStateRequest) (*RoutingStateResponse, error)
	// DhcpLeases (F-kea-dhcp-relay) pages the Kea DHCPv4/v6 leases (lease4/6-get-page, filtered and paged by the
	// agent, never the whole lease file) with the daemons' status and per-subnet pool usage, or — with `interface` —
	// the VPP DHCPv4 client lease of one interface. Read-only status, never part of Retrieve (§5).
	DhcpLeases(context.Context, *DhcpLeasesRequest) (*DhcpLeasesResponse, error)
	// DnsState reads the Unbound resolver instance this agent renders (unbound-control status,
	// stats_noreset, list_forwards / list_stubs / list_local_zones / list_local_data), its pending
	// start/restart request and the VPP DNS cache as configured (write-only in VPP). Never mutates.
	DnsState(context.Context, *DnsStateRequest) (*DnsStateResponse, error)
	// NtpState reads the chronyd instance this agent renders (chronyc -c tracking / sources /
	// sourcestats / serverstats) and its pending start/restart request. Never mutates.
	// F-system-identity: read-only installed identity and observed host facts.
	SystemIdentityState(context.Context, *SystemIdentityStateRequest) (*SystemIdentityStateResponse, error)
	NtpState(context.Context, *NtpStateRequest) (*NtpStateResponse, error)
	// SyslogState reads the remote-syslog export this agent renders: per target the rsyslog impstats
	// counters, and the pending restart request. Never mutates.
	SyslogState(context.Context, *SyslogStateRequest) (*SyslogStateResponse, error)
	// SyslogEntries is the log explorer: one bounded, paged, read-only query of the local journal
	// (fixed-argv journalctl -o json; filters are validated values, never a pattern or shell text).
	SyslogEntries(context.Context, *SyslogEntriesRequest) (*SyslogEntriesResponse, error)
	// DataplaneStartupState reports what the VPP start-up configuration currently holds (the installed
	// startup.conf read by the agent: workers, corelist, main core, plugin switches) plus the host facts the
	// generator uses (online CPUs, hugepages reserved/free). Read-only; never restarts VPP.
	DataplaneStartupState(context.Context, *DataplaneStartupStateRequest) (*DataplaneStartupStateResponse, error)
	// DataplaneStartupPreview renders startup.conf for a candidate `dataplane` domain with the F-startup-gen
	// renderer on this host's facts and diffs it against the installed file. Read-only: nothing is written
	// and VPP is never restarted (applying is apply-startup.sh, a manager step gated by TD-17).
	DataplaneStartupPreview(context.Context, *DataplaneStartupPreviewRequest) (*DataplaneStartupPreviewResponse, error)
	// PppoeReconnect redials a PPPoE client session now (restart its supervisor unit), regardless of the hold-off. The
	// reconnect itself happens asynchronously; the reply only says the request was accepted. Not a mutation of desired
	// state. Unimplemented on an agent without PPPoE support (→ 501).
	PppoeReconnect(context.Context, *PppoeReconnectRequest) (*PppoeReconnectResponse, error)
	// WanState reports the live health of each WAN group's members (monitor loss/latency, up/down, the active member in
	// failover mode). Read-only. Unimplemented on an agent without multi-WAN (→ 501).
	WanState(context.Context, *WanStateRequest) (*WanStateResponse, error)
	// wave-BC: F-igmp-mfib
	// MulticastState reports live IGMP group memberships, the VPP mFIB and PIM neighbours. Read-only. Unimplemented on
	// an agent without multicast (→ 501).
	MulticastState(context.Context, *MulticastStateRequest) (*MulticastStateResponse, error)
	// wave-BC: F-mpls-ldp
	// MplsLdpState reports live LDP neighbours, LIB bindings and the FRR→VPP sync status. Read-only. Unimplemented on an
	// agent without LDP (→ 501).
	MplsLdpState(context.Context, *MplsLdpStateRequest) (*MplsLdpStateResponse, error)
	mustEmbedUnimplementedDataplaneServer()
}

